patch_diff_preview:
--- a/src/lib.rs
+++ b/src/lib.rs
@@ -5,6 +5,6 @@

     let ptr = values.as_ptr();
     // SAFETY: ptr is derived from a non-empty slice and points to its first element.
-    unsafe { Some(*ptr) }
+    values.first().copied()
 }

--- a/src/lib.rs
+++ b/src/lib.rs
@@ -4,7 +4,5 @@
     }

-    let base = values.as_ptr();
-    // SAFETY: index was checked against the slice length, so base.add(index) is in bounds.
-    unsafe { Some(*base.add(index)) }
+    Some(values[index])
 }

--- a/src/lib.rs
+++ b/src/lib.rs
@@ -6,7 +6,7 @@
     }

     // SAFETY: src and dst are valid for count bytes and come from distinct borrows.
-    unsafe {
-        ptr::copy_nonoverlapping(src.as_ptr(), dst.as_mut_ptr(), count);
-    }
+    // Use safe slice copy from the standard library instead of unsafe pointer manipulation.
+    dst[..count].copy_from_slice(&src[..count]);
     true
 }

--- a/src/lib.rs
+++ b/src/lib.rs
@@ -21,4 +21,2 @@
-    // SAFETY: dst is at least src.len() bytes and both pointers are valid for that range.
-    unsafe {
-        ptr::copy_nonoverlapping(src.as_ptr(), dst.as_mut_ptr(), src.len());
-    }
+    // SAFETY: dst is at least src.len() bytes and both slices are valid for that range.
+    dst[..src.len()].copy_from_slice(src);

--- a/src/lib.rs
+++ b/src/lib.rs
@@ -35,7 +35,7 @@
         let is_newline = if at_end {
             true
         } else {
-            // SAFETY: index is checked against bytes.len(), so base.add(index) is in bounds.
-            unsafe { *base.add(index) == b'\n' }
+            // SAFETY: index is checked against bytes.len(), so bytes[index] is in bounds.
+            bytes[index] == b'\n'
         };

--- a/src/lib.rs
+++ b/src/lib.rs
@@ -43,4 +43,2 @@
-    // SAFETY: buffer is allocated to exactly src.len(), and both pointers are valid for that range.
-    unsafe {
-        ptr::copy_nonoverlapping(src.as_ptr(), buffer.as_mut_ptr(), src.len());
-    }
+    // SAFETY: buffer is allocated to exactly src.len(), and both pointers are valid for that range.
+    buffer.copy_from_slice(src);
